\begin{lemma}
    \label{lemma:f-g-z_j-z_k}
    Let $\bz_j,\bz_k$ be independent $N({\bf 0},\bI_n)$ random vectors.
    Let $f,h:\R^n\to\R^n$ deterministic with weakly differentiable
    components and define the random matrices $\bA,\bB\in\R^{n\times n}$
    respectively by
    $\bA = \bigl(
            \bz_j^\top f(\bz_k) \bI_n
            + f(\bz_k)\bz_j^\top
        \bigr)
        \nabla f(\bz_k)^\top
    $ and
    $\bB =
         \bigl(
         \bz_k^\top h(\bz_j) \bI_n
        + h(\bz_j) \bz_k^\top
        \bigr)
    \nabla h(\bz_j)^\top
    $.
    Assume that
    \begin{equation}
        \label{assumption-A-B-sobolev} 
    \E[\|f(\bz_k)\|^4]
    +
    \E[\|h(\bz_j)\|^4]
    +
    \E[\|\bA\|_F^2]
    +
    \E[\|\bB\|_F^2]
    < +\infty.
    \end{equation}
    Then equality
\begin{equation}
    \label{eq:equality-correlation-lemma}
\E\big[
    \big\{(\bz_j^{\pb{\top}} f(\bz_k))^2-\|f (\bz_k)\|^2 \big\}
    \big\{(\bz_k^{\pb{\top}} h(\bz_j))^2-\|h (\bz_j)\|^2 \big\}
    \big]
    =
    \E[
    \trace
    \{
        \bA \bB
    \}
    ]
    \end{equation}
holds and
$\E|\trace[\bA\bB]| \le
        4
        \E\bigl[\|\nabla f(\bz_k)\|_F^2\|f(\bz_k)\|^2\bigr]^{\frac12}
        \E\bigl[\|\nabla h(\bz_j)\|_F^2\|h(\bz_j)\|^2\bigr]^{\frac12}
$.
\end{lemma}
